/// Marks the active leaf of the tree after a branch navigation.
///
/// Ported from pi's `LeafEntry`. Appended by the storage when the session
/// moves to a different branch; [targetId] is the new leaf (or `null` for
/// the tree root).
final class LeafRecord extends SessionRecord {
  /// Creates a [LeafRecord].
  const LeafRecord({
    required super.id,
    required super.parentId,
    required super.timestamp,
    this.targetId,
  });

  /// The new active leaf, or `null` for the tree root.
  final String? targetId;

  @override
  String get type => 'leaf';

  @override
  Map<String, dynamic> payloadJson() => {'targetId': targetId};
}
/// the session file and project into context as one-line placeholder
/// markers at their original position, expandable on demand via
/// `compact_expand`.
///
/// State is expressed over stable record ids — NEVER over positions or
/// derived indexes (AC3 of #148: the stored state model is position-free;
/// the short numeric ids the model sees are computed at render time from
/// the append-only file order).
final class HiddenRangeRecord extends SessionRecord {
  /// Creates a [HiddenRangeRecord].
  const HiddenRangeRecord({
    required super.id,
    required super.parentId,
    required super.timestamp,
