+  Future<SessionSearchOutcome> searchSessionArchive(
+    SessionSearchQuery query,
+  ) async {
+    final session = _session;
+    final repo = _repo;
+    if (session == null || repo is! JsonlSessionRepo) {
+      return const SessionSearchOutcome(
+        hits: [],
+        recordsExamined: 0,
