/// boot because housekeeping metadata could not be read.
Future<List<String>> listSessionSegmentPaths(
  FileSystem fs,
  String primaryPath,
) async {
  final listed = await JsonlSessionStorage._listSessionParts(fs, primaryPath);
  return [...?listed?.parts, primaryPath];
}

